<template>
  <main class="rd-shop">
    <header class="shop-heading"><div><div class="shop-title"><h1>{{ adminView ? '商城管理' : '社团商城' }}</h1><span class="shop-test">测试</span></div><p>创作有回响，热爱有收获。</p></div><div class="shop-wallet"><Coins :size="24" /><div><small>我的创作币</small><strong>{{ me ? me.balance : '—' }}<span v-if="me"> 币</span></strong></div><a v-if="!me" href="/login/">登录</a><a v-else-if="!adminView && me.role==='admin'" href="/admin/shop/" title="管理商城" aria-label="管理商城"><Settings2 :size="20" /></a></div></header>
    <PageState v-if="adminView && !loading && me?.role!=='admin'" title="需要管理员权限" :message="me ? '当前账号不能管理商城' : '请先登录管理员账号'" />
    <template v-else>
      <div class="shop-toolbar"><nav class="shop-tabs" aria-label="商城栏目"><button v-for="item in tabs" :key="item.id" :aria-pressed="view===item.id" :class="{active:view===item.id}" @click="setView(item.id)"><component :is="item.icon" :size="17" />{{ item.label }}</button></nav><div class="shop-tools"><button v-if="adminView && view==='products'" class="shop-primary" :disabled="busy" @click="editProduct()"><Plus :size="18" />新增商品</button><button class="shop-icon" title="刷新商城" aria-label="刷新商城" :disabled="loading || busy" @click="load()"><RotateCw :size="19" /></button></div></div>
      <p v-if="message" class="shop-message" role="status">{{ message }}</p><p v-if="error" class="shop-error" role="alert">{{ error }}</p>
      <p v-if="loading" role="status" class="shop-empty">加载中…</p>
      <template v-else-if="view==='products'">
        <div v-if="!adminView" class="shop-filters"><label class="shop-search"><Search :size="18" /><input v-model="search" placeholder="搜索商品" aria-label="搜索商品" maxlength="80" @keydown.enter="loadProducts(0)"></label><label>分类<select v-model="category" aria-label="商品分类" @change="loadProducts(0)"><option value="">全部</option><option v-for="name in categories" :key="name">{{ name }}</option></select></label><button class="shop-button" :disabled="busy" @click="loadProducts(0)">搜索</button></div>
        <div class="shop-body"><section class="shop-products" aria-label="商品列表"><div v-if="!products.length" class="shop-empty"><PackageOpen :size="32" /><h2>{{ adminView ? '还没有商品' : '商品即将上架' }}</h2><p>{{ adminView ? '暂无商品记录' : '商品筹备中，敬请期待。' }}</p></div><div v-else class="shop-grid"><article v-for="product in products" :key="product.id" class="shop-product"><button class="shop-cover" :aria-label="'查看商品 '+product.title" @click="openProduct(product)"><img v-if="product.cover_url && !failedImages[product.cover_url]" :src="product.cover_url" :alt="product.title" loading="lazy" referrerpolicy="no-referrer" @error="failedImages[product.cover_url]=true"><Package v-else :size="46" /><span class="shop-category">{{ product.category }}</span></button><div class="shop-product-text"><div class="shop-product-title"><h2>{{ product.title }}</h2><span v-if="adminView" class="shop-status">{{ productStatuses[product.status] }}</span></div><p>{{ product.description || '暂无商品介绍' }}</p><div class="shop-product-bottom"><strong><Coins :size="16" />{{ product.price }} <small>创作币</small></strong><span>{{ product.stock===null ? '不限量' : product.stock===0 ? '已兑完' : '余 '+product.stock+' 件' }}</span></div><div class="shop-product-actions"><button v-if="adminView" class="shop-button" :disabled="busy" @click="editProduct(product)"><Pencil :size="15" />编辑商品</button><button v-else class="shop-button" :disabled="product.stock===0" @click="openProduct(product)">查看商品<ArrowUpRight :size="15" /></button></div></div></article></div></section><aside v-if="!adminView" class="shop-rules"><h2><Sparkles :size="18" />商城测试中</h2><p>创作币获取渠道暂未开放，商品仅供浏览。</p><small>测试积分，不支持充值、提现或转账。</small></aside></div>
      </template>
      <section v-else-if="view==='orders'" class="shop-orders"><div v-if="adminView" class="shop-order-filter"><label>订单状态<select v-model="orderFilter" aria-label="订单状态" @change="loadOrders(0)"><option value="">全部</option><option value="pending">待处理</option><option value="fulfilled">已完成</option><option value="cancelled">已取消</option></select></label></div><PageState v-if="!me" title="登录后查看兑换记录" /><div v-else-if="!orders.length" class="shop-empty"><ShoppingBag :size="30" /><h2>暂无兑换记录</h2></div><article v-for="order in orders" :key="order.id" class="shop-order"><div class="shop-order-heading"><h2>{{ order.product_title }}</h2><span class="shop-status" :class="'is-'+order.status">{{ orderStatuses[order.status] }}</span></div><p class="shop-order-meta">{{ adminView ? order.username+' · ' : '' }}{{ date(order.created_at) }} · {{ order.price }} 创作币</p><p v-if="order.note" class="shop-note">兑换备注：{{ order.note }}</p><p v-if="order.fulfillment_note" class="shop-note">处理说明：{{ order.fulfillment_note }}</p><small class="shop-order-id">订单 {{ order.id }}</small><div v-if="adminView && order.status==='pending'" class="shop-order-actions"><button class="shop-primary" :disabled="busy" @click="openOrder(order,'fulfilled')"><Check :size="16" />确认完成</button><button class="shop-button" :disabled="busy" @click="openOrder(order,'cancelled')"><Undo2 :size="16" />取消并退币</button></div></article></section>
      <section v-else class="shop-ledger"><PageState v-if="!me" title="登录后查看收支明细" /><div v-else-if="!entries.length" class="shop-empty"><ReceiptText :size="30" /><h2>暂无收支记录</h2></div><article v-for="entry in entries" :key="entry.id" class="shop-ledger-row"><div><strong>{{ entry.reason }}</strong><time>{{ date(entry.created_at) }}</time></div><b :class="{positive:entry.amount>0}">{{ entry.amount>0?'+':'' }}{{ entry.amount }} 币</b></article></section>
      <nav v-if="hasMore || offset" class="shop-pagination" aria-label="商城分页"><button class="shop-button" :disabled="busy || !offset" @click="turnPage(-20)"><ChevronLeft :size="16" />上一页</button><span>第 {{ Math.floor(offset/20)+1 }} 页</span><button class="shop-button" :disabled="busy || !hasMore" @click="turnPage(20)">下一页<ChevronRight :size="16" /></button></nav>
    </template>
    <dialog ref="detailDialog" class="shop-dialog" aria-labelledby="shop-detail-title" @cancel="guardCancel"><template v-if="selected"><header><h2 id="shop-detail-title">{{ selected.title }}</h2><button class="shop-icon" title="关闭" aria-label="关闭商品详情" :disabled="busy" @click="detailDialog.close()"><X :size="21" /></button></header><img v-if="selected.cover_url && !failedImages[selected.cover_url]" class="shop-detail-image" :src="selected.cover_url" :alt="selected.title" referrerpolicy="no-referrer" @error="failedImages[selected.cover_url]=true"><p class="shop-note">{{ selected.description || '暂无商品介绍' }}</p><div class="shop-detail-price"><strong>{{ selected.price }} 创作币</strong><span>{{ selected.stock===null?'不限量':'库存 '+selected.stock }}</span></div><template v-if="!adminView"><button v-if="!rules.redemptions_enabled" class="shop-button" disabled>测试展示 · 兑换暂未开放</button><template v-else><label v-if="me">兑换备注<textarea v-model="checkoutNote" maxlength="500" rows="2" placeholder="可填写领取方式或补充说明"></textarea></label><p v-if="dialogError" class="shop-error" role="alert">{{ dialogError }}</p><a v-if="!me" class="shop-primary" href="/login/">登录后兑换</a><button v-else class="shop-primary" :disabled="busy || selected.stock===0 || me.balance<selected.price" @click="redeem()"><ShoppingBag :size="17" />{{ selected.stock===0?'商品已兑完':me.balance<selected.price?'创作币不足':'确认兑换 · '+selected.price+' 币' }}</button></template></template></template></dialog>
    <dialog ref="editDialog" class="shop-dialog" aria-labelledby="shop-edit-title" @cancel="guardCancel"><form @submit.prevent="saveProduct"><header><h2 id="shop-edit-title">{{ editing ? '编辑商品' : '新增商品' }}</h2><button type="button" class="shop-icon" title="关闭" aria-label="关闭商品编辑" :disabled="busy" @click="editDialog.close()"><X :size="21" /></button></header><label>商品名称<input v-model="form.title" maxlength="100" required></label><label>商品介绍<textarea v-model="form.description" maxlength="4000" rows="4"></textarea></label><div class="shop-form-grid"><label>分类<input v-model="form.category" maxlength="30" required></label><label>售价（创作币）<input v-model.number="form.price" type="number" min="1" max="1000000" required></label></div><label>商品图片网址<input v-model="form.cover_url" maxlength="2000" placeholder="https://..."></label><div class="shop-form-grid"><label class="shop-check"><input v-model="unlimited" type="checkbox">不限量</label><label v-if="!unlimited">库存<input v-model.number="form.stock" type="number" min="0" max="1000000" required></label></div><label>上架状态<select v-model="form.status"><option value="draft">草稿</option><option value="published">上架</option><option value="archived">下架</option></select></label><p v-if="dialogError" class="shop-error" role="alert">{{ dialogError }}</p><footer><button type="button" class="shop-button" :disabled="busy" @click="editDialog.close()">取消</button><button class="shop-primary" :disabled="busy"><Save :size="17" />{{ busy?'保存中…':'保存商品' }}</button></footer></form></dialog>
    <dialog ref="orderDialog" class="shop-dialog" aria-labelledby="shop-order-title" @cancel="guardCancel"><form @submit.prevent="processOrder"><header><h2 id="shop-order-title">{{ orderAction==='fulfilled'?'确认完成兑换':'取消兑换并退币' }}</h2><button type="button" class="shop-icon" title="关闭" aria-label="关闭订单处理" :disabled="busy" @click="orderDialog.close()"><X :size="21" /></button></header><p>{{ selectedOrder?.product_title }} · {{ selectedOrder?.price }} 创作币</p><label>处理说明<textarea v-model="orderNote" maxlength="1000" rows="4" required></textarea></label><p v-if="dialogError" class="shop-error" role="alert">{{ dialogError }}</p><button class="shop-primary" :disabled="busy">{{ busy?'处理中…':'确认处理' }}</button></form></dialog>
  </main>
</template>
<script setup>
import { computed, nextTick, onMounted, onUnmounted, reactive, ref } from 'vue'
import { ArrowUpRight, Check, ChevronLeft, ChevronRight, Coins, Package, PackageOpen, Pencil, Plus, ReceiptText, RotateCw, Save, Search, Settings2, ShoppingBag, Sparkles, Undo2, X } from 'lucide-vue-next'
import PageState from './PageState.vue'
import { communityRequest as request } from '../lib/community-api.mjs'
const props=defineProps({adminView:Boolean})
const rules=ref({article_likes:10,article_reward:0,streak_reward:0,earning_enabled:false,redemptions_enabled:false}),me=ref(null),products=ref([]),orders=ref([]),entries=ref([]),categories=ref([]),view=ref('products'),loading=ref(true),busy=ref(false),error=ref(''),message=ref(''),offset=ref(0),hasMore=ref(false),search=ref(''),category=ref(''),orderFilter=ref(''),failedImages=reactive({})
const detailDialog=ref(null),editDialog=ref(null),orderDialog=ref(null),selected=ref(null),editing=ref(null),selectedOrder=ref(null),checkoutNote=ref(''),dialogError=ref(''),unlimited=ref(false),orderAction=ref('fulfilled'),orderNote=ref('')
const defaults=()=>({title:'',description:'',category:'社团周边',cover_url:'',price:5,stock:10,status:'draft'}),form=reactive(defaults())
const tabs=computed(()=>(props.adminView?[{id:'products',label:'商品管理',icon:Package},{id:'orders',label:'兑换订单',icon:ShoppingBag}]:[{id:'products',label:'商品',icon:Package},{id:'orders',label:'我的兑换',icon:ShoppingBag},{id:'ledger',label:'收支明细',icon:ReceiptText}]).filter(tab=>tab.id!=='orders'||rules.value.redemptions_enabled))
const productStatuses={draft:'草稿',published:'已上架',archived:'已下架'},orderStatuses={pending:'待处理',fulfilled:'已完成',cancelled:'已取消 · 已退币'}
let disposed=false,revision=0,subscription,checkoutKey='',previousFocus
const date=value=>new Date(value).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false})
function acceptPage(data,target,start){target.value=data.items;offset.value=start;hasMore.value=data.has_more}
async function fetchProducts(start=0){const url=props.adminView?'/shop/admin/products?offset='+start:'/shop/products?offset='+start+'&q='+encodeURIComponent(search.value)+'&category='+encodeURIComponent(category.value);return request(url)}
async function fetchOrders(start=0){return request((props.adminView?'/shop/admin/orders?status='+encodeURIComponent(orderFilter.value)+'&':'/shop/orders?')+'offset='+start)}
async function load(){const run=++revision;loading.value=true;error.value='';try{let identity;try{identity=await request('/shop/me')}catch(e){if(e.status!==401)throw e;identity=null}if(disposed||run!==revision)return;me.value=identity;if(identity?.rules)rules.value=identity.rules;if(props.adminView&&identity?.role!=='admin')return;let data;if(view.value==='products'){data=await fetchProducts(offset.value);if(disposed||run!==revision)return;acceptPage(data,products,offset.value);if(data.categories)categories.value=data.categories;if(data.rules)rules.value=data.rules}else if(identity){data=view.value==='orders'?await fetchOrders(offset.value):await request('/shop/ledger?offset='+offset.value);if(disposed||run!==revision)return;acceptPage(data,view.value==='orders'?orders:entries,offset.value)}else{orders.value=[];entries.value=[];hasMore.value=false}}catch(e){if(!disposed&&run===revision)error.value=e.message}finally{if(!disposed&&run===revision)loading.value=false}}
async function loadProducts(start){offset.value=start;await load()}
async function loadOrders(start){offset.value=start;await load()}
function setView(value){if(busy.value)return;view.value=value;offset.value=0;message.value='';const url=new URL(location.href);url.searchParams.set('view',value);history.replaceState({},'',url);load()}
function turnPage(delta){offset.value=Math.max(0,offset.value+delta);load()}
function guardCancel(event){if(busy.value)event.preventDefault()}
async function showDialog(dialog){previousFocus=document.activeElement;await nextTick();dialog.value.showModal()}
function openProduct(product){selected.value=product;checkoutNote.value='';checkoutKey=crypto.randomUUID();dialogError.value='';showDialog(detailDialog)}
function editProduct(product){editing.value=product||null;Object.assign(form,product?Object.fromEntries(Object.keys(defaults()).map(key=>[key,product[key]])):defaults());unlimited.value=product?.stock===null;dialogError.value='';showDialog(editDialog)}
async function saveProduct(){if(busy.value)return;busy.value=true;dialogError.value='';try{const body={...form,stock:unlimited.value?null:form.stock,...(editing.value?{expected_revision:editing.value.revision}:{})};await request('/shop/admin/products'+(editing.value?'/'+editing.value.id:''),{method:editing.value?'PUT':'POST',body});editDialog.value.close();message.value='商品已保存';offset.value=0;await load()}catch(e){dialogError.value=e.message}finally{busy.value=false}}
async function redeem(){if(busy.value || !rules.value.redemptions_enabled)return;busy.value=true;dialogError.value='';try{await request('/shop/orders',{method:'POST',body:{product_id:selected.value.id,expected_revision:selected.value.revision,request_key:checkoutKey,note:checkoutNote.value}});detailDialog.value.close();message.value='兑换成功，等待管理员处理';view.value='orders';offset.value=0;await load()}catch(e){dialogError.value=e.message}finally{busy.value=false}}
function openOrder(order,status){selectedOrder.value=order;orderAction.value=status;orderNote.value='';dialogError.value='';showDialog(orderDialog)}
async function processOrder(){if(busy.value)return;busy.value=true;dialogError.value='';try{await request('/shop/admin/orders/'+selectedOrder.value.id,{method:'POST',body:{status:orderAction.value,fulfillment_note:orderNote.value}});orderDialog.value.close();message.value=orderAction.value==='cancelled'?'订单已取消，创作币已退回':'订单已完成';await load()}catch(e){dialogError.value=e.message}finally{busy.value=false}}
function communityUpdated(){if(!busy.value)load()}
onMounted(()=>{const initial=new URLSearchParams(location.search).get('view');if(tabs.value.some(tab=>tab.id===initial))view.value=initial;load();window.addEventListener('rd:community-updated',communityUpdated);for(const dialog of [detailDialog,editDialog,orderDialog])dialog.value.addEventListener('close',()=>previousFocus?.focus?.());subscription=window.__api?.auth.onAuthStateChange(event=>{if(event==='INITIAL_SESSION')return;++revision;me.value=null;products.value=[];orders.value=[];entries.value=[];for(const dialog of [detailDialog,editDialog,orderDialog])dialog.value?.close();load()}).data.subscription})
onUnmounted(()=>{disposed=true;++revision;subscription?.unsubscribe();window.removeEventListener('rd:community-updated',communityUpdated)})
</script>
<style scoped>
